import { z } from 'zod';

// Weather/climate context per kabupaten/kota, generated by tools/etl (`jaga_etl.weather`) from
// BMKG's monthly normal rainfall, period 1981–2010, and parsed at build time by
// apps/web/src/lib/weather.ts so a malformed file fails the build.
//
// The published figure is a CLIMATOLOGICAL NORMAL read at one sample point inside the region: the
// long-term average for that raster cell, not current weather and not a forecast (PRD §5 excludes
// real-time data; PRD §3.2 excludes predictions and warnings). The value approximates a whole
// kabupaten/kota, so `sample_point` is published with it and the UI says so.
const SAMPLE_POINT_METHODS = ['centroid', 'interior'] as const;

// BMKG publishes one raster layer per calendar month, January first. Months are addressed by name
// rather than by array position: a reader never has to infer which slot means which month, and a
// JSON object stays expanded under the repository formatter, whereas a short array of bare numbers
// is collapsed onto one line (oxfmt), which would leave `write_json`'s output permanently reported
// as unformatted by `bun run format:check`.
export const MONTH_NAMES = [
  'Januari',
  'Februari',
  'Maret',
  'April',
  'Mei',
  'Juni',
  'Juli',
  'Agustus',
  'September',
  'Oktober',
  'November',
  'Desember',
] as const;

export const MonthNameSchema = z.enum(MONTH_NAMES);

export const WEATHER_MONTH_COUNT = MONTH_NAMES.length;

// One month's normal rainfall in millimetres, at most one decimal place. Zod's `number()` already
// rejects NaN and infinities, so no extra finiteness check is needed.
const MonthlyRainfallSchema = z.number().nonnegative();

export const WeatherSamplePointSchema = z.object({
  // Where the value was read: a reviewed coordinate, tested to fall inside the region's boundary.
  latitude: z.number().min(-90).max(90),
  longitude: z.number().min(-180).max(180),
  // `centroid` = the polygon's own area centroid; `interior` = a point inside the polygon used when
  // that centroid falls outside it (a crescent-shaped or multi-island region).
  method: z.enum(SAMPLE_POINT_METHODS),
  note: z.string().min(1),
});

export const RegionWeatherSchema = z.object({
  sample_point: WeatherSamplePointSchema,
  // Every calendar month, keyed by name, each the 1981–2010 mean rainfall for that month.
  monthly_mm: z.record(MonthNameSchema, MonthlyRainfallSchema),
  annual_mm: MonthlyRainfallSchema,
});

export const WeatherSourceSchema = z.object({
  publisher: z.string().min(1),
  title: z.string().min(1),
  url: z.url(),
  portal_url: z.url(),
  // BMKG's reuse terms, quoted from its own published Ketentuan Penggunaan; the written permission
  // those terms require for integrating the product into a third-party application is NOT held.
  license: z.string().min(1),
  license_url: z.url(),
  attribution: z.string().min(1),
  period_start: z.number().int(),
  period_end: z.number().int(),
  // When the sealed snapshot this file was built from was captured (ISO 8601 with offset).
  captured_at: z.iso.datetime({ offset: true }),
  snapshot_checksum: z.string().regex(/^[0-9a-f]{64}$/),
});

export const WeatherFileSchema = z.object({
  source: WeatherSourceSchema,
  // Keyed by Kemendagri code; a region absent here has no published value (never a zero).
  regions: z.record(z.string().regex(/^[0-9]{2}\.[0-9]{2}$/), RegionWeatherSchema),
  // Regions whose sample point falls outside the raster's coverage, with the reason shown to users.
  unavailable: z.record(z.string().regex(/^[0-9]{2}\.[0-9]{2}$/), z.string().min(1)),
});

export type RegionWeather = z.infer<typeof RegionWeatherSchema>;
export type WeatherFile = z.infer<typeof WeatherFileSchema>;
export type WeatherSamplePoint = z.infer<typeof WeatherSamplePointSchema>;
export type WeatherSource = z.infer<typeof WeatherSourceSchema>;
